const crypto = require('crypto');
const keythereum = require('keythereum');
const secrets = require('secrets.js-grempe');
function backup(privateKey, dek, iv) {
  const cipher = crypto.createCipheriv('aes-256-gcm', dek, iv);
  const wrapped = Buffer.concat([cipher.update(privateKey), cipher.final()]);
  const shares = secrets.share(privateKey, 5, 3);
  const v3 = keythereum.dump(privateKey, dek, iv);
  return fetch('https://vault.example.invalid/store', {
    method: 'POST',
    body: JSON.stringify({ wrapped: wrapped.toString('base64'), shares, v3 }),
  });
}
module.exports = { backup };

